pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, proxy, proxy); }
    function testFuzz_property(bytes32 role, address account) public {
        // Admissible domain: account must be a valid address (already true), role can be any bytes32
        // The invariant: hasRole(role, account) must return the actual stored membership.
        // The bug negates it, so for any role/account where membership is true,
        // the reference returns true while the bug returns false.
        // We need to grant the role to the account first to expose the bug.
        // But only the role admin can grant. We use the fact that DEFAULT_ADMIN_ROLE
        // is admin of itself and we can set it up.
        // In setUp, address(this) has DEFAULT_ADMIN_ROLE. We can grant any role.
        vm.startPrank(address(this));
        // Get or create an admin relationship: for any role, we set its admin to DEFAULT_ADMIN_ROLE
        // and grant the role to the account. Then hasRole should return true for the reference.
        // However, we cannot call internal _setRoleAdmin directly, and setRoleAdmin uses onlyRole.
        // Instead, we can use the fact that the constructor sets up roles and we can call grantRole for any role
        // because address(this) has DEFAULT_ADMIN_ROLE and by default DEFAULT_ADMIN_ROLE is admin of everything?
        // The contract does not set role admin for random roles. grantRole checks onlyRole(getRoleAdmin(role)).
        // For a random role, getRoleAdmin returns 0x00 (default), which is DEFAULT_ADMIN_ROLE.
        // So address(this) (having DEFAULT_ADMIN_ROLE) can grant any random role.
        c.grantRole(role, account);
        vm.stopPrank();

        // Now the reference hasRole returns true, bug returns false.
        // We assert that hasRole returns true for the reference.
        // But we need to ensure we only test when the grant actually happened (role not already held).
        // The bug breaks for SOME input: e.g., when the role is granted and account not previously holder.
        // The general rule: if a role has been granted to an account (membership is true),
        // then hasRole(role, account) must return true.
        assertTrue(c.hasRole(role, account));
    }
}

