pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address account) public {
        // Drive the contract to set up a known membership state.
        // First, grant the role to the account using _grantRole via _setupRole.
        // We need an admin to be able to grant. The setUp already gives address(this) the TIMELOCK_ADMIN_ROLE,
        // which is admin of itself and of PROPOSER_ROLE and EXECUTOR_ROLE.
        // We will use grantRole as the public interface that calls _grantRole internally.
        // To grant a role, the caller must have the role's admin role.
        // For simplicity, we focus on roles where the admin role is itself (TIMELOCK_ADMIN_ROLE),
        // or where the caller already has the admin role.
        // By default, address(this) has TIMELOCK_ADMIN_ROLE, which is admin of PROPOSER_ROLE and EXECUTOR_ROLE.
        // We can grant PROPOSER_ROLE or EXECUTOR_ROLE to the fuzzed account, or even TIMELOCK_ADMIN_ROLE (since it's self-administered).
        // We use a constant salt role that we know address(this) can grant.
        bytes32 roleToGrant = keccak256(abi.encodePacked("TEST_ROLE", role));
        // Make sure this test role has TIMELOCK_ADMIN_ROLE as admin, which we can set since we have TIMELOCK_ADMIN_ROLE.
        // We can use c.grantRole, but to make it admin we need the admin to be something we have.
        // The easiest is to use TIMELOCK_ADMIN_ROLE as the admin, because we already have it.
        // However, we cannot directly set admin for arbitrary roles from outside without a public function,
        // and the contract does not expose _setRoleAdmin publicly. It only sets admin for the three predefined roles in constructor.
        // So we must use one of the three predefined roles whose admin we have.
        // We have TIMELOCK_ADMIN_ROLE, and PROPOSER_ROLE and EXECUTOR_ROLE have TIMELOCK_ADMIN_ROLE as admin.
        // Therefore, we can grant PROPOSER_ROLE or EXECUTOR_ROLE to the account.
        // We choose PROPOSER_ROLE.
        bytes32 targetRole = c.PROPOSER_ROLE();

        vm.prank(address(this));
        c.grantRole(targetRole, account);

        // Now record the actual stored membership by calling hasRole on the reference.
        // To do this, we need to ensure that the contract we deployed is the reference.
        // But the test file includes the reference contract by definition (the given C is reference).
        // So we just call c.hasRole and expect true.
        // The buggy version would return false.

        // We also need to ensure that the role was not already held before granting, but if it was, it stays true.
        // In both cases, after grantRole, the membership must be true.
        assertTrue(c.hasRole(targetRole, account), "hasRole should return true after successful grantRole");
    }
}

