        // correct admin for roles whose admin we know.
        // We need a general invariant: if we can set a role's admin to a specific value (e.g. through the constructor
        // or by exploiting the fact that we can grant the admin role), then getRoleAdmin must return that value.
        // Since there's no public setter for role admin, we use the pre-set roles. The fuzzer can vary the role.
        bytes32 expectedAdmin;
        if (role == c.TIMELOCK_ADMIN_ROLE()) {
            expectedAdmin = c.TIMELOCK_ADMIN_ROLE();
        } else if (role == c.PROPOSER_ROLE()) {
            expectedAdmin = c.TIMELOCK_ADMIN_ROLE();
        } else if (role == c.EXECUTOR_ROLE()) {
            expectedAdmin = c.TIMELOCK_ADMIN_ROLE();
        } else {
            // For any other role not set, adminRole should default to 0
            expectedAdmin = bytes32(0);
        }
        vm.assume(adminRole == expectedAdmin); // We only test when the expected admin matches a known case.
        assertEq(c.getRoleAdmin(role), expectedAdmin);
    }
}

