pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role, bytes32 adminRole) public {
        vm.assume(role != 0x00);
        vm.assume(adminRole != 0x00);
        vm.prank(address(c));
        c.updateDelay(0);
        vm.stopPrank();

        vm.prank(address(this));
        c.grantRole(TIMELOCK_ADMIN_ROLE(), address(this));
        vm.stopPrank();

        address(c).call(abi.encodeWithSignature("_setRoleAdmin(bytes32,bytes32)", role, adminRole));

        bytes32 returnedAdmin = c.getRoleAdmin(role);
        assertTrue(returnedAdmin == adminRole);
    }

    function TIMELOCK_ADMIN_ROLE() internal pure returns (bytes32) {
        return keccak256("TIMELOCK_ADMIN_ROLE");
    }
}
